-- DataVista Analytics — PostgreSQL schema (v1)
-- Baseline from the Backend Database Schema document, hardened:
--   * UUIDs are generated by the application layer so the schema runs on both
--     managed PostgreSQL and the embedded PGlite engine used for local dev/CI.
--   * CHECK constraints replace ENUM types (portable, easier to migrate).
--   * Import jobs, dataset rows, dataset permissions, notifications and
--     forecast runs are present (required before production, per doc §10).

CREATE TABLE IF NOT EXISTS users (
  id            UUID PRIMARY KEY,
  name          VARCHAR(150) NOT NULL,
  email         VARCHAR(255) NOT NULL UNIQUE,
  password_hash TEXT NOT NULL,
  role          VARCHAR(20) NOT NULL DEFAULT 'viewer'
                CHECK (role IN ('super_admin','admin','analyst','viewer')),
  is_active     BOOLEAN NOT NULL DEFAULT TRUE,
  token_version INTEGER NOT NULL DEFAULT 0,
  last_login_at TIMESTAMPTZ,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at    TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS datasets (
  id            UUID PRIMARY KEY,
  user_id       UUID NOT NULL REFERENCES users(id),
  name          VARCHAR(255) NOT NULL,
  original_name VARCHAR(255) NOT NULL,
  storage_key   TEXT NOT NULL,
  file_type     VARCHAR(20) NOT NULL CHECK (file_type IN ('csv','xlsx')),
  file_size     INTEGER NOT NULL DEFAULT 0,
  row_count     INTEGER NOT NULL DEFAULT 0,
  column_count  INTEGER NOT NULL DEFAULT 0,
  columns       JSONB NOT NULL DEFAULT '[]'::jsonb,
  warnings      JSONB NOT NULL DEFAULT '[]'::jsonb,
  duplicate_rows INTEGER NOT NULL DEFAULT 0,
  status        VARCHAR(30) NOT NULL DEFAULT 'pending'
                CHECK (status IN ('pending','processing','ready','failed')),
  error_code    VARCHAR(60),
  error_message TEXT,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at    TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS dataset_import_jobs (
  id           UUID PRIMARY KEY,
  dataset_id   UUID NOT NULL REFERENCES datasets(id) ON DELETE CASCADE,
  status       VARCHAR(30) NOT NULL DEFAULT 'pending'
               CHECK (status IN ('pending','processing','ready','failed')),
  attempts     INTEGER NOT NULL DEFAULT 0,
  progress     INTEGER NOT NULL DEFAULT 0,
  error_code   VARCHAR(60),
  error_message TEXT,
  started_at   TIMESTAMPTZ,
  finished_at  TIMESTAMPTZ,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Parsed rows. JSONB keeps the MVP schema-agnostic; swap for Parquet/DuckDB
-- when analytical volume grows (doc §8).
CREATE TABLE IF NOT EXISTS dataset_rows (
  dataset_id UUID NOT NULL REFERENCES datasets(id) ON DELETE CASCADE,
  row_index  INTEGER NOT NULL,
  data       JSONB NOT NULL,
  PRIMARY KEY (dataset_id, row_index)
);

-- Value counts per column, used by the chart builder to suggest categories.
CREATE TABLE IF NOT EXISTS dataset_value_counts (
  dataset_id UUID NOT NULL REFERENCES datasets(id) ON DELETE CASCADE,
  column_name VARCHAR(255) NOT NULL,
  values     JSONB NOT NULL DEFAULT '[]'::jsonb,
  PRIMARY KEY (dataset_id, column_name)
);

CREATE TABLE IF NOT EXISTS dataset_permissions (
  id         UUID PRIMARY KEY,
  dataset_id UUID NOT NULL REFERENCES datasets(id) ON DELETE CASCADE,
  user_id    UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  permission VARCHAR(20) NOT NULL CHECK (permission IN ('view','edit')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (dataset_id, user_id)
);

CREATE TABLE IF NOT EXISTS dashboards (
  id          UUID PRIMARY KEY,
  user_id     UUID NOT NULL REFERENCES users(id),
  name        VARCHAR(255) NOT NULL,
  description TEXT,
  layout      JSONB NOT NULL DEFAULT '{"columns":12,"widgets":[]}'::jsonb,
  is_default  BOOLEAN NOT NULL DEFAULT FALSE,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS charts (
  id            UUID PRIMARY KEY,
  dataset_id    UUID NOT NULL REFERENCES datasets(id) ON DELETE CASCADE,
  user_id       UUID NOT NULL REFERENCES users(id),
  title         VARCHAR(255) NOT NULL,
  chart_type    VARCHAR(50) NOT NULL
                CHECK (chart_type IN ('bar','pie','line','area','scatter','histogram')),
  configuration JSONB NOT NULL,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at    TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS dashboard_widgets (
  id           UUID PRIMARY KEY,
  dashboard_id UUID NOT NULL REFERENCES dashboards(id) ON DELETE CASCADE,
  chart_id     UUID NOT NULL REFERENCES charts(id) ON DELETE CASCADE,
  position     JSONB NOT NULL DEFAULT '{"x":0,"y":0,"w":6,"h":4}'::jsonb,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS dashboard_shares (
  id           UUID PRIMARY KEY,
  dashboard_id UUID NOT NULL REFERENCES dashboards(id) ON DELETE CASCADE,
  user_id      UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  permission   VARCHAR(20) NOT NULL CHECK (permission IN ('view','edit')),
  created_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (dashboard_id, user_id)
);

CREATE TABLE IF NOT EXISTS forecast_runs (
  id            UUID PRIMARY KEY,
  dataset_id    UUID NOT NULL REFERENCES datasets(id) ON DELETE CASCADE,
  user_id       UUID NOT NULL REFERENCES users(id),
  target_column VARCHAR(255) NOT NULL,
  time_field    VARCHAR(255),
  model_type    VARCHAR(100),
  horizon       INTEGER NOT NULL DEFAULT 12,
  metrics       JSONB,
  results       JSONB,
  status        VARCHAR(30) NOT NULL DEFAULT 'pending'
                CHECK (status IN ('pending','processing','ready','failed')),
  error_message TEXT,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS notifications (
  id         UUID PRIMARY KEY,
  user_id    UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  type       VARCHAR(50) NOT NULL,
  title      VARCHAR(255) NOT NULL,
  message    TEXT NOT NULL,
  link       VARCHAR(255),
  is_read    BOOLEAN NOT NULL DEFAULT FALSE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS activity_logs (
  id         UUID PRIMARY KEY,
  user_id    UUID REFERENCES users(id) ON DELETE SET NULL,
  action     VARCHAR(150) NOT NULL,
  details    JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_datasets_user ON datasets(user_id);
CREATE INDEX IF NOT EXISTS idx_datasets_status ON datasets(status);
CREATE INDEX IF NOT EXISTS idx_dashboards_user ON dashboards(user_id);
CREATE INDEX IF NOT EXISTS idx_charts_dataset ON charts(dataset_id);
CREATE INDEX IF NOT EXISTS idx_charts_user ON charts(user_id);
CREATE INDEX IF NOT EXISTS idx_widgets_dashboard ON dashboard_widgets(dashboard_id);
CREATE INDEX IF NOT EXISTS idx_shares_user ON dashboard_shares(user_id);
CREATE INDEX IF NOT EXISTS idx_shares_dashboard ON dashboard_shares(dashboard_id);
CREATE INDEX IF NOT EXISTS idx_activity_user_time ON activity_logs(user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_activity_created ON activity_logs(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_notifications_user ON notifications(user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_forecast_dataset ON forecast_runs(dataset_id);
CREATE INDEX IF NOT EXISTS idx_jobs_dataset ON dataset_import_jobs(dataset_id);
